ROOT=Path(__file__).resolve().parents[2]
A1=ROOT/'reading/french/a1/passages.jsonl'
CANON=ROOT/'reading/french/a2/passages.jsonl'
SCHEMA=ROOT/'reading/schema/passage.schema.json'
LEX=ROOT/'french_top1000.csv'
EXPECTED_BLOB='1606e3a560c830855d3c2a10d1d027cbab564b14'
FORMS=('oublier','clé','perdre','retrouver','recevoir','envoyer','vérifier','payer','numéro','carte')
REVIEW_PAIRS=(('raison','résultat'),('décision','information'),('important','différent'),('habitude','expérience'),('choix','idée'))

def deck():
 out={}
 with LEX.open(encoding='utf-8',newline='') as f:
  for row in csv.DictReader(f):
   form=(row.get('Front') or '').strip();b=row.get('Back') or ''
   mr=re.search(r'Rank:\s*(\d+)',b);mm=re.search(r'Meaning:\s*(.+)',b);mp=re.search(r'Part of speech:\s*(.+)',b)
   if form and mr and mm and mp:out[form]={'rank':int(mr.group(1)),'sense':mm.group(1).strip(),'pos':mp.group(1).strip()}
 return out
def tid(r):return f'fr-rank-{r:04d}'
def cnt(text,f):return len(re.findall(rf'(?<!\w){re.escape(f)}(?!\w)',text,flags=re.I|re.UNICODE))
def prior(rows):
 d={}
 for r in rows:
  for t in r.get('new_lexical_targets',[]):
   if isinstance(t,dict) and t.get('form'):d.setdefault(t['form'],[]).append(t)
 return d
def nt(f,text,D):
 s=D[f];n=cnt(text,f)
 if n<1:raise AssertionError(f'{f}: no exact new-target exposure')
 return {'id':tid(s['rank']),'form':f,'lemma':f,'intended_sense':s['sense'],'part_of_speech':s['pos'],'register':'contemporary standard','variety':None,'context_strategy':['scenario_resolution'],'first_introduced':True,'exposures_in_text':n,'source_lexicon':'french_top1000.csv','source_rank':s['rank'],'beyond_base':False}
def rev(f,P):
 h=P.get(f,[])
 if len(h)!=1:raise AssertionError(f'{f}: expected one prior deliberate target, got {len(h)}')
 return {'id':h[0]['id'],'form':f,'review_stage':'R2','representation':'running_text','expected_exposure_number':None}
def cur(f,D):return {'id':tid(D[f]['rank']),'form':f,'review_stage':'R1','representation':'summary','expected_exposure_number':None}
def qa(items,ids):
 q=[];a=[]
 for i,(typ,prompt,answer,forms) in enumerate(items,1):
  qi=f'q{i}';ai=f'a{i}';x={'id':qi,'type':typ,'prompt':prompt,'answer_id':ai}
  if forms:x['target_ids']=[ids[f] for f in forms]
  q.append(x);a.append({'id':ai,'question_id':qi,'answer':answer,'explanation':''})
 return q,a
def mk(s,new,reviews,ids,speed=False):
 q,a=qa(s['items'],ids);text=s['text']
 return {'id':s['id'],'language':'fr','cefr':'A2','unit':3,'sequence':s['sequence'],'revision':1,'title':s['title'],'passage_type':s['ptype'],'genre':s['genre'],'domains':s['domains'],'topics':s['topics'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':new,'review_lexical_targets':reviews,'grammar_targets':s['grammar'],'discourse_targets':s['discourse'],'questions':q,'answer_key':a,'speed_training':{'timed':speed,'benchmark_eligible':speed,'comprehension_gate':0.8,'new_word_policy':'none' if speed else 'controlled','notes':'Generation-stage French A2 Unit 03; final language-wide audit deferred.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['Guarded French A2 Unit 03 generation batch.','A1+A2 freshness, source identity, A2 word band, exact review visibility, local target linkage, continuity and zero-new checkpoint are enforced.']},'paired_text_group':None,'prerequisites':['French A2 Units 01-02 canonical corpus'],'difficulty_notes_internal':'A2 practical problems and information handling with explicit cause/effect and reference chains.','reader_tags':['unit_role:'+s['ptype'],'generation_batch','french_a2_u03']}

