def checkpoint():
 return {'id':'fr-a2-u03-p06','sequence':18,'ptype':'checkpoint','title':'Contrôler l’information utile','genre':'cumulative practical-strategy summary','domains':['personal','educational','public'],'topics':['problem solving','information','verification'],'text':'''Dans les situations récentes, Camille apprend à traiter les petits problèmes de façon plus organisée. Si elle risque d’oublier une clé, elle choisit un endroit fixe pour la ranger. Quand elle pense perdre un objet, elle décrit ce qu’elle cherche afin de pouvoir le retrouver. Pour un projet, elle peut envoyer un fichier et demander à l’autre personne de confirmer qu’elle a pu le recevoir. Avant un achat ou un service, Camille préfère vérifier les informations avant de payer. Lorsqu’un accueil lui demande un numéro, elle regarde attentivement quel numéro se trouve sur la bonne carte. Ces actions ont un point commun : Camille ne réagit plus seulement à la première impression. Elle identifie d’abord l’information utile, choisit une action, puis contrôle le résultat. Cette méthode ne supprime pas tous les problèmes, mais elle réduit les erreurs et l’aide à expliquer plus clairement pourquoi une solution a fonctionné dans une situation précise.''','grammar':[{'id':'fr-a2-u03-condition-purpose-review','role':'integration','description':'integrate conditional and purpose expressions'}],'discourse':[{'id':'fr-a2-u03-identify-act-check','role':'integration','description':'summarize identify-act-check as a practical problem-solving cycle'}],'items':[('gist','Quelle méthode générale Camille développe-t-elle ?','Elle identifie l’information utile, agit, puis contrôle le résultat.',[]),('literal_detail','Que fait-elle pour une clé qu’elle risque d’oublier ?','Elle choisit un endroit fixe pour la ranger.',['oublier','clé']),('vocabulary_in_context','Que signifie « retrouver » dans ce résumé ?','Trouver de nouveau un objet qu’on ne trouvait plus.',['retrouver']),('vocabulary_in_context','Que signifie « recevoir » ici ?','Obtenir un fichier envoyé par une autre personne.',['recevoir','envoyer']),('cause_effect','Pourquoi vérifie-t-elle avant de payer ?','Pour réduire le risque d’une information ou d’un montant incorrect.',['vérifier','payer']),('single_word_definition','Que signifie « perdre » ici ?','Ne plus savoir où se trouve un objet qu’on avait.',['perdre']),('reference_resolution','Dans « quel numéro se trouve sur la bonne carte », quel élément doit-elle identifier ?','Le numéro utile demandé par le service.',['numéro','carte']),('contrast','Lequel décrit l’action de faire partir un fichier : « envoyer » ou « recevoir » ?','envoyer',['envoyer','recevoir']),('cloze_transfer','Complète : Avant de _____, je contrôle le total.','payer',['payer']),('summary','Résume le cycle de résolution présenté.','Identifier l’information utile, choisir une action, puis vérifier ce qui s’est produit.',[])]}

def build(a1,a2,D):
 P=prior(a1+a2);fail=[]
 for f in FORMS:
  if f not in D:fail.append(f'{f}:missing_lexicon')
  if P.get(f):fail.append(f'{f}:already_scheduled')
 if fail:raise AssertionError('freshness/source failures: '+', '.join(fail))
 out=[]
 for s in specs():
  new=[nt(f,s['text'],D) for f in s['forms']];reviews=[rev(f,P) for f in s['reviews']];ids={t['form']:t['id'] for t in new+reviews};out.append(mk(s,new,reviews,ids))
 cp=checkpoint();reviews=[cur(f,D) for f in FORMS];ids={t['form']:t['id'] for t in reviews};out.append(mk(cp,[],reviews,ids,True));return out

def main():
 blob=subprocess.check_output(['git','hash-object',str(CANON)],text=True).strip()
 if blob!=EXPECTED_BLOB:raise AssertionError(f'A2 canonical blob drift: {blob} != {EXPECTED_BLOB}')
 a1=[json.loads(x) for x in A1.read_text(encoding='utf-8').splitlines() if x.strip()];a2=[json.loads(x) for x in CANON.read_text(encoding='utf-8').splitlines() if x.strip()]
 if len(a1)!=60 or a1[-1]['id']!='fr-a1-u10-p06':raise AssertionError('unexpected A1 prerequisite state')
 if len(a2)!=12 or [r['sequence'] for r in a2]!=list(range(1,13)) or a2[-1]['id']!='fr-a2-u02-p06':raise AssertionError('expected exact A2 Unit02 frontier')
 D=deck();unit=build(a1,a2,D);V=Draft202012Validator(json.loads(SCHEMA.read_text(encoding='utf-8')));old={t['id'] for r in a1+a2 for t in r.get('new_lexical_targets',[]) if isinstance(t,dict) and t.get('id')}
 if [r['sequence'] for r in unit]!=list(range(13,19)) or [r['id'] for r in unit]!=[f'fr-a2-u03-p{i:02d}' for i in range(1,7)]:raise AssertionError('Unit03 continuity failure')
 newids=[]
 for r in unit:
  errs=sorted(V.iter_errors(r),key=lambda e:list(e.path))
  if errs:raise AssertionError(f"{r['id']}: schema {[e.message for e in errs[:6]]}")
  if not 140<=r['word_count']<=220:raise AssertionError(f"{r['id']}: A2 word band {r['word_count']}")
  if len(r['questions'])!=10 or len(r['answer_key'])!=10:raise AssertionError(f"{r['id']}: assessment count")
  amap={a['question_id']:a['id'] for a in r['answer_key']};decl={t['id'] for fld in ('new_lexical_targets','review_lexical_targets') for t in r.get(fld,[]) if isinstance(t,dict)}
  for q in r['questions']:
   if amap.get(q['id'])!=q['answer_id'] or any(x not in decl for x in q.get('target_ids',[])):raise AssertionError(f"{r['id']} {q['id']}: linkage/target declaration")
  for t in r['new_lexical_targets']:
   s=D.get(t['form'])
   if t['id'] in old or not s or t['source_rank']!=s['rank'] or t['id']!=tid(s['rank']) or cnt(r['text'],t['form'])!=t['exposures_in_text']:raise AssertionError(f"{r['id']}: source/exposure/reintroduction drift {t}")
   newids.append(t['id'])
  for t in r['review_lexical_targets']:
   if t['representation'] in {'running_text','summary'} and cnt(r['text'],t['form'])<1:raise AssertionError(f"{r['id']}: invisible review {t['form']}")
 if len(newids)!=10 or len(set(newids))!=10 or unit[-1]['new_lexical_targets']!=[]:raise AssertionError('Unit03 lexical-cycle invariant')
 CANON.write_text(''.join(json.dumps(r,ensure_ascii=False,sort_keys=True)+'\n' for r in a2+unit),encoding='utf-8')
 print(json.dumps({'status':'PASS','level':'A2','unit':3,'appended_passages':6,'a2_passages':18,'word_counts':{r['id']:r['word_count'] for r in unit},'new_targets':[{'form':f,'rank':D[f]['rank'],'id':tid(D[f]['rank'])} for f in FORMS],'questions':60,'answers':60,'p06_new_targets':0},ensure_ascii=False))
if __name__=='__main__':main()
